243	
244	  const [isAuthenticated, setIsAuthenticated] = useState(false);
245	
246	  useEffect(() => {
247	    getSession()
248	      .then(session => {
249	        const payload     = session.getIdToken().payload;
250	        const username    = payload['cognito:username'];
251	        const accountType = payload['custom:accountType'] || 'individual';
252	        setIsAuthenticated(true);
253	        setUserRole(accountType);
254	        setShopId(username);
255	        sessionStorage.setItem('userRole', accountType);
256	        sessionStorage.setItem('shopId',   username);
257	        // now fetch + merge your config from DynamoDB…
258	      })
259	      .catch(() => {
260	        // no session => not logged in
261	      });
262	  }, []);
263	  
264	  
265	
266	  +  /* ────────────────────────────────────────────────────────────────
267	  +     1)  When the user becomes authenticated (or changes role), pull
268	  +         the server-side config once and merge it over whatever we
269	  +         already have in state. If there’s nothing stored yet on the
270	  +         server, that GET just returns {}, so the defaults stay.
271	  +  ───────────────────────────────────────────────────────────────── */
272	  useEffect(() => {
273	    if (!isAuthenticated) return;
274	    (async () => {
275	      try {
276	        const remote = await fetchConfig();          // GET /config?shop_id=…
277	        if (remote && Object.keys(remote).length) {
278	          setConfig(prev => ({ ...prev, ...remote }));
279	        }
280	      } catch (err) {
281	        console.error('Could not load remote config → keep local', err);
282	      }
283	    })();
284	  }, [isAuthenticated, userRole]);
285	  // Save config to localStorage whenever it changes, using role-specific key
286	  useEffect(() => {
287	      const storageKey = getConfigStorageKey(shopId);
288	      console.log(`Saving config for shop=${shopId} to ${storageKey}`);
289	      localStorage.setItem(storageKey, JSON.stringify(config));
290	    }, [config, shopId]);
291	
292	  // Check for existing authentication on mount
293	  useEffect(() => {
294	    const storedRole = sessionStorage.getItem('userRole');
295	    if (storedRole) {
296	      setIsAuthenticated(true);
297	      setUserRole(storedRole);
298	    }
299	  }, []);
300	
301	  // Authentication with role-based access
302	
303	  const login = async (username, password) => {
304	    try {
305	      const session = await signIn({ username, password });
306	      const accountType = session.getIdToken().payload['custom:accountType'];
307	      setIsAuthenticated(true);
308	      setShopId(username);
309	      setUserRole(accountType);
310	      sessionStorage.setItem('shopId', username);
311	      sessionStorage.setItem('userRole', accountType);
312	      // fetch + merge config…
313	      return { success: true };
314	    } catch (err) {
315	      return { success: false, message: err.message };
316	    }
317	  };
318	  
319	  const signOut = () => {
320	    // clear client state
321	    sessionStorage.removeItem('idToken');
322	    sessionStorage.removeItem('shopId');
323	    sessionStorage.removeItem('userRole');
324	  
325	    // Build the exact logout URL Cognito expects:
326	    const domain      = process.env.REACT_APP_COGNITO_DOMAIN;       // e.g. https://your-domain.auth.us-east-2.amazoncognito.com
327	    const clientId    = process.env.REACT_APP_COGNITO_CLIENT_ID;   // your app client ID
328	    const logoutUri   = process.env.REACT_APP_REDIRECT_URI;        // MUST match exactly your "Allowed sign-out URL"
329	    
330	    window.location.assign(
331	      `${domain}/logout` +
332	      `?client_id=${clientId}` +
333	      `&logout_uri=${encodeURIComponent(logoutUri)}`
334	    );
335	  };
336	
337	  // Get current user role
338	  const getUserRole = () => {
339	    return userRole || sessionStorage.getItem('userRole');
340	  };
341	
342	  // Update configuration
343	  /* ────────────────────────────────────────────────────────────────
344	  +     2)  updateConfig → optimistic local update *and* PUT to DynamoDB
345	  +  ───────────────────────────────────────────────────────────────── */
346	  const updateConfig = async (newConfig) => {
347	    setConfig(newConfig);                        // UI feels instant
348	    try { await saveConfig(newConfig); }         // PUT /config
349	    catch (e) {
350	      console.error('saveConfig failed – state is still updated', e);
351	    }
352	  };
353	
354	  // Reset to default configuration based on role
355	  const resetConfig = async () => {
356	    const role = getUserRole();
357	    let defaultCfg = defaultConfig;
358	    
359	    if (role === 'enterprise') {
360	      defaultCfg = defaultEnterpriseConfig;
361	    } else if (role === 'individual') {
362	      defaultCfg = defaultIndividualConfig;
363	    }
364	    
365	    setConfig(defaultCfg);
366	    localStorage.setItem('appConfig', JSON.stringify(defaultCfg));
367	    try { await saveConfig(defaultCfg); } catch (e) {
368	      console.error('saveConfig after reset failed', e);
369	    }
370	  };
371	  
372	  return (
373	    <ConfigContext.Provider
374	    value={{ config, updateConfig, resetConfig, isAuthenticated, login, signOut, getUserRole, setUserRole }}
375	    >
376	      {children}
377	    </ConfigContext.Provider>
378	  );
379	}
380	
381	ConfigProvider.propTypes = {
382	  children: PropTypes.node.isRequired,
383	};

