        setUserRole(accountType);
        setShopId(username);
        sessionStorage.setItem('userRole', accountType);
        sessionStorage.setItem('shopId',   username);
        // now fetch + merge your config from DynamoDB…
      })
      .catch(() => {
        // no session => not logged in
      });
  }, []);



