/* ────────────────────────────────────────────────────────────────
   api.js – SAM back-end helper with Cognito auth & mock fallback
   ----------------------------------------------------------------
   – GET /config?shop_id=…         (Cognito-protected)
   – PUT /config                   (Cognito-protected)
   – GET /appointments?shop_id=…
   – POST /appointments/book
   – GET /workers
   ---------------------------------------------------------------- */

   import {
    mockAppointments,
    mockWorkers,
    generateEmptyMockData,
  } from './mockData';

  /* ── env & helpers ────────────────────────────────────────────── */
  const API_BASE = process.env.REACT_APP_BACKEND_URL;

  const shopId = () => sessionStorage.getItem('shopId') || 'demo-shop';

  const isMockMode = () =>
    !API_BASE ||
    (API_BASE.startsWith('http://localhost') && !navigator.onLine);

  const getDatabaseConfig = () => {
    try {
      const cfg = JSON.parse(localStorage.getItem('appConfig') || '{}');
      return cfg.database || {};
    } catch {
      return {};
    }
  };

  /** Build headers with the JWT we stored after Hosted-UI login */
  async function authHeader() {
    const token = sessionStorage.getItem('idToken');
    return {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    };
  }

  /* ────────────────────────────────────────────────────────────────
     1)  CONFIG  – GET & PUT (Cognito protected)
     ---------------------------------------------------------------- */
  export async function fetchConfig(shop = shopId()) {
    if (isMockMode()) return {};
    const headers = await authHeader();
    const r = await fetch(`${API_BASE}/config?shop_id=${shop}`, { headers });
    if (!r.ok) throw new Error(r.statusText);
    return r.json(); // {} if nothing saved yet
  }

  export async function saveConfig(cfg, shop = shopId()) {
    if (isMockMode()) return;
    const headers = await authHeader();
    const payload = { ...cfg, shop_id: shop }; // partition key for DynamoDB
    const r = await fetch(`${API_BASE}/config`, {
      method: 'PUT',
      headers,
      body: JSON.stringify(payload),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json();
  }

  /* ────────────────────────────────────────────────────────────────
     2)  APPOINTMENTS – GET
     ---------------------------------------------------------------- */
  export async function fetchAppointments(dateISO) {
    /* Offline / mock */
    if (isMockMode()) {
      return mockAppointments.filter((a) => !dateISO || a.date === dateISO);
    }

    const headers = await authHeader();
    const base = `${API_BASE}/appointments?shop_id=${shopId()}`;
    const url = dateISO ? `${base}&date=${dateISO}` : base;

    const r = await fetch(url, { headers });
    if (!r.ok) throw new Error(r.statusText);
    return (await r.json()).appointments;
  }

  /* ────────────────────────────────────────────────────────────────
     3)  WORKERS – GET
     ---------------------------------------------------------------- */
  export async function fetchWorkers() {
    const role = sessionStorage.getItem('userRole');

    /* 1) Individual tenant = single “worker” (the shop owner) */
    if (role === 'individual') {
      const ownerId   = sessionStorage.getItem('shopId');
      const ownerName = sessionStorage.getItem('workerName') || ownerId;
      return [{ worker_id: ownerId, name: ownerName }];
    }

    /* 2) Mock / offline */
    if (isMockMode()) {
      const empty = getDatabaseConfig().useEmptyData === true;
      return empty ? generateEmptyMockData().workers : mockWorkers;
    }

    /* 3) Live call */
    const headers = await authHeader();
    const res     = await fetch(`${API_BASE}/workers`, { headers });
    if (!res.ok) throw new Error(`Failed to fetch workers: ${res.statusText}`);

    const { workers = [] } = await res.json();
    return workers.map((w) => ({
      worker_id: w.worker_id,
      name: w.name || w.worker_id,
      ...w,
    }));
  }

  /* ────────────────────────────────────────────────────────────────
     4)  APPOINTMENTS – POST
     ---------------------------------------------------------------- */
  export async function bookAppointment(data) {
    if (isMockMode()) return legacyMockBook(data);

    const headers = await authHeader();
    const payload = { ...data, shop_id: shopId() };

    const r = await fetch(`${API_BASE}/appointments/book`, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
    });
    if (!r.ok) throw new Error(await r.text());
    return r.json();
  }

  /* ────────────────────────────────────────────────────────────────
     5)  CUSTOMERS stub (later)
     ---------------------------------------------------------------- */
  export const fetchCustomers = async () => [];

  /* ────────────────────────────────────────────────────────────────
     6)  ChatGPT helper (unchanged here)
     ---------------------------------------------------------------- */
  export async function callChatApi(messages) {
    /* left as-is – your existing code goes here */
  }

  /* ────────────────────────────────────────────────────────────────
     7)  Legacy local-mock book helper
     ---------------------------------------------------------------- */
  function legacyMockBook(appt) {
    const withId = {
      ...appt,
      id:
        appt.id ||
        `${appt.date}-${appt.start_time}-${appt.worker_id}-${Date.now()}`,
    };
    mockAppointments.push(withId);
    return Promise.resolve({
      success: true,
      message: 'Appointment saved locally (mock mode)',
      id: withId.id,
    });
  }

  /* ────────────────────────────────────────────────────────────────
     8)  convenient default export
     ---------------------------------------------------------------- */
  export default {
    fetchConfig,
    saveConfig,
    fetchAppointments,
    fetchWorkers,
    fetchCustomers,
    bookAppointment,
    callChatApi,
  };

import json
import os
import boto3
from boto3.dynamodb.conditions import Key
from decimal import Decimal
from urllib.parse import parse_qs
from datetime import datetime, timedelta

# ──────────────────────────────────────────────
# Helpers
# ──────────────────────────────────────────────
def json_safe(item: dict):
    """
    Recursively walk a dict returned by boto3 DDB client and
    convert:
      • Decimal → int/float
      • set     → list
    """
    safe = {}
    for k, v in item.items():
        if isinstance(v, Decimal):
            safe[k] = int(v) if v % 1 == 0 else float(v)
        elif isinstance(v, set):
            safe[k] = list(v)
        elif isinstance(v, dict):
            safe[k] = json_safe(v)
        else:
            safe[k] = v
    return safe

def extract_shop_id(event, default="demo-shop"):
    """Read ?shop_id=… from query-string, fallback to default."""
    qs = event.get("rawQueryString") or ""
    params = dict(pair.split("=", 1) for pair in qs.split("&") if "=" in pair)
    return params.get("shop_id", default)


class DecimalEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Decimal):
            return int(obj) if obj % 1 == 0 else float(obj)
        return super().default(obj)

SHOP_KEY = 'shop_id'          # partition key
SORT_KEY = 'sort_key'         # range key  =>  "{date}#{start_time}#{worker_id}"

def build_sort_key(date_, time_, worker_id):
    return f"{date_}#{time_}#{worker_id}"

def response(status, body):
    return {
        "statusCode": status,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "http://localhost:3000",
            "Access-Control-Allow-Headers": "Content-Type,Authorization",
            "Access-Control-Allow-Methods": "OPTIONS,GET,POST,PUT"
        },
        "body": json.dumps(body, cls=DecimalEncoder)
    }

# ──────────────────────────────────────────────
# AWS objects
# ──────────────────────────────────────────────
APPOINTMENTS_TABLE = os.environ.get('APPOINTMENTS_TABLE', 'Appointments')
WORKERS_TABLE      = os.environ.get('WORKERS_TABLE', 'Workers')
CONFIGS_TABLE = os.environ.get('CONFIGS_TABLE', 'Configs')

dynamodb = boto3.resource('dynamodb')

configs_table = dynamodb.Table(CONFIGS_TABLE)
appointments_table = dynamodb.Table(APPOINTMENTS_TABLE)
workers_table      = dynamodb.Table(WORKERS_TABLE)

# ──────────────────────────────────────────────
# Lambda entry
# ──────────────────────────────────────────────
def lambda_handler(event, context):
    raw_path = event.get('rawPath') or event.get('path', '')
    method   = event.get('requestContext', {}).get('http', {}).get('method', '')

    # Cognito injects: event['requestContext']['authorizer']['jwt']['claims']
    # ─── Extract tenant + plan from Cognito JWT ─────────────────
    # (Api Gateway JWT Authorizer must be configured)
    claims = event['requestContext']['authorizer']['jwt']['claims']
    shop_id = claims['cognito:username']      # now every tenant is isolated
    account_type = claims.get('custom:accountType', 'individual')

    # ─── Inject shop_id into query params for existing handlers ─
    qsp = event.get('queryStringParameters') or {}
    qsp['shop_id'] = shop_id
    event['queryStringParameters'] = qsp

    # strip stage prefix if present (/Prod or /dev)
    segments = [seg for seg in raw_path.split('/') if seg]
    if segments and segments[0].lower() in {'prod', 'dev', 'stage'}:
        path = '/' + '/'.join(segments[1:])
    else:
        path = raw_path

    # CORS pre-flight
    if method == "OPTIONS":
        return {
            "statusCode": 200,
            "headers": {
                "Access-Control-Allow-Origin": "http://localhost:3000",
                "Access-Control-Allow-Headers": "Content-Type,Authorization",
                "Access-Control-Allow-Methods": "OPTIONS,GET,POST,PUT"
            },
            "body": ""
        }

    # ─────────────── routes ────────────────
    if path == '/workers'            and method == 'GET':
        return get_workers(event)

    if path == '/appointments'       and method == 'GET':
        return get_appointments(event)

    if path == '/appointments/all'   and method == 'GET':
        return get_all_appointments(event)

    if path == '/appointments/book'  and method == 'POST':
        return book_appointment(event)
    if path == '/config' and method == 'GET':
        return get_config(event)

    if path == '/config' and method == 'PUT':
        return put_config(event)    

    return response(404, {"message": "Not Found"})


# ──────────────────────────────────────────────
# GET /workers?shop_id=xyz
# ──────────────────────────────────────────────
def get_workers(event):
    shop_id = event['queryStringParameters']['shop_id']
    if not shop_id:
        return response(400, {"message": "Missing shop_id"})

    try:
        res = workers_table.query(
            KeyConditionExpression=Key('shop_id').eq(shop_id)
        )
        items = [json_safe(i) for i in res.get('Items', [])]
        return response(200, {"workers": items})

    except Exception as e:
        print("Error querying workers table:", e)
        return response(500, {
            "message": "Error querying workers table",
            "error"  : str(e)
        })


# ──────────────────────────────────────────────
# GET /appointments?shop_id=xyz&date=YYYY-MM-DD
# ──────────────────────────────────────────────
def get_appointments(event):
    qs   = parse_qs(event.get("rawQueryString", ""))
    date = qs.get("date",    [None])[0]
    shop = qs.get("shop_id", [None])[0]

    if not shop:
        return response(400, {"message": "Missing shop_id"})

    try:
        if date:
            data = appointments_table.query(
                KeyConditionExpression=Key(SHOP_KEY).eq(shop) &
                                       Key(SORT_KEY).begins_with(date)
            )
        else:                             # just give me every appt for that shop
            data = appointments_table.query(
                KeyConditionExpression=Key(SHOP_KEY).eq(shop)
            )
        return response(200, {"appointments": data.get('Items', [])})
    except Exception as e:
        print("Query error:", e)
        return response(500, {"message": "Query failed", "error": str(e)})

# ──────────────────────────────────────────────
# GET /appointments/all?shop_id=xyz  (dev tool)
# ──────────────────────────────────────────────
def get_all_appointments(event):
    qs   = parse_qs(event.get("rawQueryString", ""))
    shop = qs.get("shop_id", [None])[0]

    try:
        if shop:
            data = appointments_table.query(
                KeyConditionExpression=Key(SHOP_KEY).eq(shop)
            )
            items = data.get('Items', [])
        else:                           # full table scan – dev only
            items = appointments_table.scan().get('Items', [])
        return response(200, {"appointments": items})
    except Exception as e:
        print("Scan error:", e)
        return response(500, {"message": "Error", "error": str(e)})

# ──────────────────────────────────────────────
# CONFIG FUNCTIONS GET and PUT
# ──────────────────────────────────────────────

def get_config(event):
    shop = event['queryStringParameters']['shop_id']
    if not shop:
        return response(400, {"message": "Missing shop_id"})

    res = configs_table.get_item(Key={"shop_id": shop})
    return response(200, res.get("Item", {}))


def put_config(event):
    try:
        body = json.loads(event.get("body") or "{}")
    except json.JSONDecodeError as e:
        return response(400, {"message": "Invalid JSON", "error": str(e)})

    # ignore any shop_id in the payload—use Cognito's
    claims  = event['requestContext']['authorizer']['jwt']['claims']
    shop    = claims['cognito:username']
    if not shop:
        return response(400, {"message": "shop_id required in body"})

    item = {**body, "shop_id": shop}
    configs_table.put_item(Item=item)
    return response(200, {"success": True})

# ──────────────────────────────────────────────
# POST /appointments/book   (JSON body)
# ──────────────────────────────────────────────
def book_appointment(event):
    try:
        body = json.loads(event.get("body", "{}"))
    except json.JSONDecodeError as e:
        return response(400, {"message": "Invalid JSON", "error": str(e)})

    # tenant owner from Cognito
    claims  = event['requestContext']['authorizer']['jwt']['claims']
    shop_id = claims['cognito:username']
    worker_id  = body.get("worker_id")
    date       = body.get("date")
    start_time = body.get("start_time")
    duration   = int(body.get("duration", 40))
    client     = body.get("client_name", "Cliente")

    if not all([shop_id, worker_id, date, start_time]):
        return response(400, {"message": "Required: shop_id, worker_id, date, start_time"})

    # ── business-hour / Sunday checks ─────────────────────────────
    try:
        requested_start = datetime.strptime(f"{date} {start_time}", "%Y-%m-%d %H:%M")
    except ValueError as e:
        return response(400, {"message": "Data/hora inválida", "error": str(e)})

    if requested_start.weekday() == 6:      # domingo
        return response(400, {"message": "Não agendamos aos domingos."})

    if requested_start.time() < datetime.strptime("07:00", "%H:%M").time():
        return response(400, {"message": "Antes das 07:00."})

    if (requested_start + timedelta(minutes=duration)).time() > datetime.strptime("19:00", "%H:%M").time():
        return response(400, {"message": "Após as 19:00."})

    # ── write item with conditional-put to prevent double-book ─
    sort_key = build_sort_key(date, start_time, worker_id)
    item = {
        SHOP_KEY:   shop_id,
        SORT_KEY:   sort_key,
        "date":       date,
        "start_time": start_time,
        "worker_id":  worker_id,
        "duration":   duration,
        "client_name": client,
        "status":     "booked"
    }

    try:
        appointments_table.put_item(
            Item=item,
            ConditionExpression=f"attribute_not_exists({SORT_KEY})"
        )
        return response(200, {"success": True, "appointment": item})
    except appointments_table.meta.client.exceptions.ConditionalCheckFailedException:
        return response(409, {"message": "Horário já reservado"})
    except Exception as e:
        print("PutItem error:", e)
        return response(500, {"message": "Erro ao agendar", "error": str(e)})

# ──────────────────────────────────────────────
# PUBLIC HANDLER
# ──────────────────────────────────────────────
def public_handler(event, context):
    return {
        "statusCode": 200,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps({"ok": True})
    }

import React from 'react';
import {
  Paper,
  Typography,
  Divider,
  Grid,
  TextField,
} from '@mui/material';
import { useConfig } from '../../../context/ConfigContext';

export default function BusinessConfig() {
  const { config, updateConfig } = useConfig();

  // Handler for business settings changes
  const handleBusinessChange = (field, value) => {
    updateConfig({
      ...config,
      business: {
        ...(config.business || {}),
        [field]: value
      }
    });
  };

  return (
    <Paper sx={{ p: 3, borderRadius: 2, maxHeight: 'calc(100vh - 160px)', overflow: 'auto' }}>
      <Typography variant="h5" gutterBottom>
        Informações da Empresa
      </Typography>
      <Typography variant="body2" color="text.secondary" paragraph>
        Configure as informações básicas e horários de funcionamento.
      </Typography>
      <Divider sx={{ my: 3 }} />

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <TextField
            label="Nome da Empresa"
            fullWidth
            value={config?.business?.name || ''}
            onChange={(e) => handleBusinessChange('name', e.target.value)}
            margin="normal"
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Tipo de Negócio"
            fullWidth
            value={config?.business?.type || ''}
            onChange={(e) => handleBusinessChange('type', e.target.value)}
            margin="normal"
            helperText="Ex: Barbearia, Salão de Beleza, Consultório, etc."
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Horário de Abertura"
            type="time"
            fullWidth
            value={config?.business?.openHours || '07:00'}
            onChange={(e) => handleBusinessChange('openHours', e.target.value)}
            margin="normal"
            InputLabelProps={{
              shrink: true,
            }}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Horário de Fechamento"
            type="time"
            fullWidth
            value={config?.business?.closeHours || '19:00'}
            onChange={(e) => handleBusinessChange('closeHours', e.target.value)}
            margin="normal"
            InputLabelProps={{
              shrink: true,
            }}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Último Horário Disponível"
            type="time"
            fullWidth
            value={config?.business?.lastAppointmentTime || '18:20'}
            onChange={(e) => handleBusinessChange('lastAppointmentTime', e.target.value)}
            margin="normal"
            InputLabelProps={{
              shrink: true,
            }}
            helperText="Último horário disponível para marcação"
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Dias Fechados"
            fullWidth
            value={config?.business?.closedDays?.join(', ') || 'Domingo'}
            onChange={(e) => handleBusinessChange('closedDays', e.target.value.split(', '))}
            margin="normal"
            helperText="Separe os dias por vírgula. Ex: Domingo, Feriados"
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Duração do Atendimento (minutos)"
            type="number"
            fullWidth
            value={config?.business?.appointmentDuration || 40}
            onChange={(e) => handleBusinessChange('appointmentDuration', parseInt(e.target.value))}
            margin="normal"
            InputProps={{ inputProps: { min: 5, step: 5 } }}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Intervalo de Horários (minutos)"
            type="number"
            fullWidth
            value={config?.business?.appointmentInterval || 10}
            onChange={(e) => handleBusinessChange('appointmentInterval', parseInt(e.target.value))}
            margin="normal"
            InputProps={{ inputProps: { min: 5, step: 5 } }}
            helperText="Intervalo entre os horários disponíveis"
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            label="Endereço Completo"
            fullWidth
            multiline
            rows={2}
            value={config?.business?.address || ''}
            onChange={(e) => handleBusinessChange('address', e.target.value)}
            margin="normal"
            helperText="Endereço completo do estabelecimento"
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="Telefone de Contato"
            fullWidth
            value={config?.business?.phone || ''}
            onChange={(e) => handleBusinessChange('phone', e.target.value)}
            margin="normal"
            helperText="Telefone principal para contato"
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <TextField
            label="E-mail de Contato"
            fullWidth
            value={config?.business?.email || ''}
            onChange={(e) => handleBusinessChange('email', e.target.value)}
            margin="normal"
            helperText="E-mail para contato"
          />
        </Grid>
      </Grid>
    </Paper>
  );
}

