315	      return { success: false, message: err.message };
316	    }
317	  };
318	  
319	  const signOut = () => {
320	    // clear client state
321	    sessionStorage.removeItem('idToken');
322	    sessionStorage.removeItem('shopId');
323	    sessionStorage.removeItem('userRole');
