339	    return userRole || sessionStorage.getItem('userRole');
340	  };
341	
342	  // Update configuration
343	  /* ────────────────────────────────────────────────────────────────
344	  +     2)  updateConfig → optimistic local update *and* PUT to DynamoDB
345	  +  ───────────────────────────────────────────────────────────────── */
346	  const updateConfig = async (newConfig) => {
347	    setConfig(newConfig);                        // UI feels instant
348	    try { await saveConfig(newConfig); }         // PUT /config
349	    catch (e) {
350	      console.error('saveConfig failed – state is still updated', e);
351	    }
352	  };
353	
354	  // Reset to default configuration based on role
355	  const resetConfig = async () => {
356	    const role = getUserRole();
357	    let defaultCfg = defaultConfig;
358	    
359	    if (role === 'enterprise') {
360	      defaultCfg = defaultEnterpriseConfig;
361	    } else if (role === 'individual') {
362	      defaultCfg = defaultIndividualConfig;
363	    }
364	    
365	    setConfig(defaultCfg);
366	    localStorage.setItem('appConfig', JSON.stringify(defaultCfg));
367	    try { await saveConfig(defaultCfg); } catch (e) {
368	      console.error('saveConfig after reset failed', e);
369	    }
370	  };
371	  
372	  return (
373	    <ConfigContext.Provider
374	    value={{ config, updateConfig, resetConfig, isAuthenticated, login, signOut, getUserRole, setUserRole }}
375	    >
376	      {children}
377	    </ConfigContext.Provider>
378	  );
379	}
380	
381	ConfigProvider.propTypes = {
382	  children: PropTypes.node.isRequired,
383	};

