/**
 * Reset to default configuration based on user role
 * @returns {Promise<void>}
 */
const resetConfig = async () => {
  if (!shopId) {
    console.error('Cannot reset config: No shop ID available');
    return;
  }

  const role = getUserRole();
  let defaultCfg;

  // Select appropriate default based on user role
  switch (role) {
    case 'enterprise':
      defaultCfg = defaultEnterpriseConfig;
      break;
    case 'individual':
      defaultCfg = defaultIndividualConfig;
      break;
    default:
      defaultCfg = defaultConfig;
  }

  // Apply reset locally
  setConfig(defaultCfg);

  try {
    // Persist to localStorage
    const storageKey = getConfigStorageKey(shopId);
    localStorage.setItem(storageKey, JSON.stringify(defaultCfg));

    // Persist to server
    const configWithShopId = { ...defaultCfg, shop_id: shopId };
    await saveConfig(configWithShopId);
  } catch (error) {
    console.error('Failed to persist configuration reset:', error);
  }
};

