   236	
   237	/**
   238	 * Provider component for configuration context
   239	 * Manages state for configuration, authentication, and user roles
   240	 * @param {Object} props Component props
   241	 * @param {React.ReactNode} props.children Child components
   242	 */
   243	export function ConfigProvider({ children }) {
   244	  /**
   245	   * Generates a unique localStorage key for shop-specific configuration
   246	   * @param {string} shop - The shop ID (username)
   247	   * @returns {string} - The localStorage key for this shop's configuration
   248	   */
   249	  const getConfigStorageKey = (shop) => `appConfig_${shop || 'default'}`;
   250	
   251	  // User and shop state
   252	  const [userRole, setUserRole] = useState(() => {
   253	    try {
   254	      return sessionStorage.getItem('userRole') || null;
   255	    } catch (error) {
   256	      console.error('Error reading userRole from sessionStorage:', error);
   257	      return null;
   258	    }
   259	  });
   260	  
   261	  const [shopId, setShopId] = useState(() => {
   262	    try {
   263	      return sessionStorage.getItem('shopId') || null;
   264	    } catch (error) {
   265	      console.error('Error reading shopId from sessionStorage:', error);
   266	      return null;
   267	    }
   268	  });
   269	  
   270	  /**
   271	   * Initialize config state with saved config or default based on role
   272	   * Falls back to role-specific defaults if no saved configuration exists
   273	   */
   274	  const [config, setConfig] = useState(() => {
   275	    try {
   276	      const shop = sessionStorage.getItem('shopId');
   277	      const storageKey = getConfigStorageKey(shop);
   278	      
   279	      // First try to load from shop-specific storage key
   280	      try {
   281	        const saved = localStorage.getItem(storageKey);
   282	        if (saved) {
   283	          return JSON.parse(saved);
   284	        }
   285	      } catch (error) {
   286	        console.error(`Error reading config from ${storageKey}:`, error);
   287	      }
   288	  
   289	      // If no shop-specific config found, check for legacy 'appConfig' key
   290	      try {
   291	        const legacyConfig = localStorage.getItem('appConfig');
   292	        if (legacyConfig && shop) {
   293	          // Migrate legacy config to shop-specific storage
   294	          localStorage.setItem(storageKey, legacyConfig);
   295	          localStorage.removeItem('appConfig'); // Clean up legacy key
   296	          console.log(`Migrated legacy config to ${storageKey}`);
   297	          return JSON.parse(legacyConfig);
   298	        }
   299	      } catch (error) {
   300	        console.error('Error migrating legacy config:', error);
   301	      }
   302	  
   303	      // Fallback based on role
   304	      const role = sessionStorage.getItem('userRole');
   305	      if (role === 'enterprise') return defaultEnterpriseConfig;
   306	      if (role === 'individual') return defaultIndividualConfig;
   307	      return defaultConfig;
   308	    } catch (error) {
   309	      console.error('Error initializing config, falling back to default', error);
   310	      return defaultConfig;
   311	    }
   312	  });
   313	
   314	  const [isAuthenticated, setIsAuthenticated] = useState(false);
   315	
   316	  /**
   317	   * Fetch user session on mount and set authentication state
   318	   */
   319	  useEffect(() => {
   320	    getSession()
   321	      .then(session => {
   322	        if (!session) return;
   323	        
   324	        try {
   325	          const payload = session.getIdToken().payload;
   326	          const username = payload['cognito:username'];
   327	          const accountType = payload['custom:accountType'] || 'individual';
   328	          
   329	          setIsAuthenticated(true);
   330	          setUserRole(accountType);
   331	          setShopId(username);
   332	          
   333	          try {
   334	            sessionStorage.setItem('userRole', accountType);
   335	            sessionStorage.setItem('shopId', username);
   336	          } catch (error) {
   337	            console.error('Error setting session storage items:', error);
   338	          }
   339	        } catch (error) {
   340	          console.error('Error processing session data:', error);
   341	        }
   342	      })
   343	      .catch((error) => {
   344	        // No session => not logged in
   345	        console.log('No active session found:', error);
   346	      });
   347	  }, []);
   348	  
   349	  /**
   350	   * Fetch server-side config when user becomes authenticated or changes role
   351	   * Merges remote config with local config
   352	   */
   353	  useEffect(() => {
   354	    if (!isAuthenticated || !shopId) return;
   355	    
   356	    (async () => {
   357	      try {
   358	        const remote = await fetchConfig(shopId);  // GET /config?shop_id=shopId
   359	        if (remote && Object.keys(remote).length) {
   360	          setConfig(prev => ({ ...prev, ...remote }));
   361	        }
   362	      } catch (err) {
   363	        console.error('Could not load remote config → keeping local', err);
   364	      }
   365	    })();
   366	  }, [isAuthenticated, userRole, shopId]);
   367	
   368	  /**
   369	   * Save config to localStorage whenever it changes, using shop-specific key
   370	   */
   371	  useEffect(() => {
   372	    if (!shopId) return;
   373	    
   374	    try {
   375	      const storageKey = getConfigStorageKey(shopId);
   376	      console.log(`Saving config for shop=${shopId} to ${storageKey}`);
   377	      localStorage.setItem(storageKey, JSON.stringify(config));
   378	    } catch (error) {
   379	      console.error(`Error saving config to localStorage for shop=${shopId}:`, error);
   380	    }
   381	  }, [config, shopId]);
   382	
   383	  /**
   384	   * Check for existing authentication on mount
   385	   */
   386	  useEffect(() => {
   387	    try {
   388	      const storedRole = sessionStorage.getItem('userRole');
   389	      const storedShopId = sessionStorage.getItem('shopId');
   390	      
   391	      if (storedRole && storedShopId) {
   392	        setIsAuthenticated(true);
   393	        setUserRole(storedRole);
   394	        setShopId(storedShopId);
   395	      }
   396	    } catch (error) {
   397	      console.error('Error checking existing authentication:', error);
   398	    }
   399	  }, []);
   400	
   401	  /**
   402	   * Authenticate user and set session data
   403	   * @param {string} username - User's username
   404	   * @param {string} password - User's password
   405	   * @returns {Object} Result of login attempt
   406	   */
   407	  const login = async (username, password) => {
   408	    try {
   409	      const session = await signIn({ username, password });
   410	      if (!session) {
   411	        return { success: false, message: 'Failed to get session data' };
   412	      }
   413	      
   414	      try {
   415	        const accountType = session.getIdToken().payload['custom:accountType'] || 'individual';
   416	        
   417	        setIsAuthenticated(true);
   418	        setShopId(username);
   419	        setUserRole(accountType);
   420	        
   421	        try {
   422	          sessionStorage.setItem('shopId', username);
   423	          sessionStorage.setItem('userRole', accountType);
   424	        } catch (storageError) {
   425	          console.error('Error setting session storage during login:', storageError);
   426	        }
   427	        
   428	        return { success: true };
   429	      } catch (parseError) {
   430	        console.error('Error parsing session data:', parseError);
   431	        return { success: false, message: 'Error processing login response' };
   432	      }
   433	    } catch (err) {
   434	      return { success: false, message: err.message || 'Authentication failed' };
   435	    }
   436	  };
   437	  
   438	  /**
   439	   * Sign out user and redirect to logout URL
   440	   */
   441	  const signOut = () => {
   442	    try {
   443	      // Clear client state
   444	      sessionStorage.removeItem('idToken');
   445	      sessionStorage.removeItem('shopId');
   446	      sessionStorage.removeItem('userRole');
   447	    
   448	      // Build the exact logout URL Cognito expects
   449	      const domain = process.env.REACT_APP_COGNITO_DOMAIN;
   450	      const clientId = process.env.REACT_APP_COGNITO_CLIENT_ID;
   451	      const logoutUri = process.env.REACT_APP_REDIRECT_URI;
   452	      
   453	      if (!domain || !clientId || !logoutUri) {
   454	        console.error('Missing environment variables for Cognito logout');
   455	        window.location.href = '/';
   456	        return;
   457	      }
   458	      
   459	      window.location.assign(
   460	        `${domain}/logout` +
   461	        `?client_id=${clientId}` +
   462	        `&logout_uri=${encodeURIComponent(logoutUri)}`
   463	      );
   464	    } catch (error) {
   465	      console.error('Error during sign out:', error);
   466	      // Fallback to homepage redirect
   467	      window.location.href = '/';
   468	    }
   469	  };
   470	
   471	  /**
   472	   * Get current user role from state or session storage
   473	   * @returns {string|null} The user role
   474	   */
   475	  const getUserRole = () => {
   476	    if (userRole) return userRole;
   477	    
   478	    try {
   479	      return sessionStorage.getItem('userRole') || null;
   480	    } catch (error) {
   481	      console.error('Error getting user role from session storage:', error);
   482	      return null;
   483	    }
   484	  };
   485	
   486	  /**
   487	   * Update configuration both locally and on the server
   488	   * Performs optimistic local update and then syncs with server
   489	   * @param {Object} newConfig - The new configuration
   490	   */
   491	  const updateConfig = async (newConfig) => {
   492	    if (!newConfig) {
   493	      console.error('Invalid config provided to updateConfig');
   494	      return;
   495	    }
   496	    
   497	    try {
   498	      // Update local state immediately for responsive UI
   499	      setConfig(newConfig);
   500	      
   501	      // Ensure shop_id is explicitly included in the config
   502	      const configWithShopId = { 
   503	        ...newConfig, 
   504	        shop_id: shopId || sessionStorage.getItem('shopId') || 'default'
   505	      };
   506	      
   507	      // Save to server
   508	      await saveConfig(configWithShopId);
   509	    } catch (error) {
   510	      console.error('Error in updateConfig:', error);
   511	      // Note: We don't rollback local state as it's an optimistic update
   512	    }
   513	  };
   514	
   515	  /**
   516	   * Reset configuration to default based on user role
   517	   * Updates both local state and server
   518	   */
   519	  const resetConfig = async () => {
   520	    try {
   521	      const role = getUserRole();
   522	      let defaultCfg = defaultConfig;
   523	      
   524	      if (role === 'enterprise') {
   525	        defaultCfg = defaultEnterpriseConfig;
   526	      } else if (role === 'individual') {
   527	        defaultCfg = defaultIndividualConfig;
   528	      }
   529	
   530	      // Ensure shop_id is included
   531	      const configWithShopId = {
   532	        ...defaultCfg,
   533	        shop_id: shopId || sessionStorage.getItem('shopId') || 'default'
   534	      };
   535	      
   536	      // Update local state
   537	      setConfig(configWithShopId);
   538	      
   539	      // Update localStorage with shop-specific key
   540	      const currentShopId = shopId || sessionStorage.getItem('shopId');
   541	      if (currentShopId) {
   542	        const storageKey = getConfigStorageKey(currentShopId);
   543	        try {
   544	          localStorage.setItem(storageKey, JSON.stringify(configWithShopId));
   545	        } catch (storageError) {
   546	          console.error(`Error saving reset config to ${storageKey}:`, storageError);
   547	        }
   548	      }
   549	      
   550	      // Save to server
   551	      await saveConfig(configWithShopId);
   552	    } catch (error) {
   553	      console.error('Error in resetConfig:', error);
   554	    }
   555	  };
   556	  
   557	  // Expose context values
