   567	    shopId
   568	  };
   569	  
   570	  return (
   571	    <ConfigContext.Provider value={contextValue}>
   572	      {children}
   573	    </ConfigContext.Provider>
   574	  );
   575	}
   576	
   577	ConfigProvider.propTypes = {
